        chair_center_y = (chair_patch.upper + chair_patch.lower) / 2
        if abs(chair_center_x - person_center_x) < 50 and abs(chair_center_y - person_center_y) < 50:
            if person_patch.llm_query("What color is the chair?", long_answer=False) == "brown":
                return chair_patch
    return person_patch

