modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    horse_patches = image_patch.find("horse")

    if not man_patches or not horse_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2 for p in man_patches]
    horse_centers = [(p.left + p.right) / 2 for p in horse_patches]

    man_on_horse = [m for m, h in zip(man_centers, horse_centers) if abs(m - h) < 50]

    if not man_on_horse:
        return image_patch

    man_patches_filtered = [man_patches[i] for i in range(len(man_patches)) if (man_centers[i] - horse_centers[man_on_horse.index(min(abs(m - h) for m, h in zip(man_centers, horse_centers)))) < 50)]

    return max(man_patches_filtered, key=lambda p: p.vertical_center)

